[tool error]
{
  "ok": false,
  "name": "place_callout",
  "error": {
    "type": "command_failed",
    "message": "give exactly one of target (a point), target_entity (what to point at) or target_anchor (a station, offset or named point of an alignment)",
    "hint": "name the thing rather than the point: target_entity takes an id from find_entities or hit_test and the engine computes a point on it, curves included; target_anchor takes '86+50@15R' or 'PC-2'. Both work from a sheet, through its viewport.",
    "example": {
      "space": "model",
      "target_entity": "BASE:LN-017",
      "at": "mid",
      "position": [
        4300.0,
        7200.0
      ],
      "content": "EP 15' RT",
      "layer": "V-ANNO-TEXT"
    }
  },
  "warnings": []
}

